select date_trunc('week', started_at) as week_start, date_trunc('quarter', started_at) as quarter_start, count(*) as event_count, count_if(device = 'mobile') as mobile_events, count(distinct id) as distinct_ids, max(started_at) as last_seen, grouping_id() as gid from sessions group by grouping sets ((date_trunc('week', started_at), date_trunc('quarter', started_at)), (date_trunc('week', started_at)), ()) having distinct_ids >= 1 order by event_count desc;
